std::string decimal_to_binary(int n) {
    /**
     * Converts a non-negative integer to binary and returns it as a string.
     *
     * @param n A non-negative integer.
     * @return A string containing the binary representation of the input integer.
     *
     * Note: If the input is negative, the function will throw a std::invalid_argument exception.
     */
    if (n < 0) {
        throw std::invalid_argument("Input must be a non-negative integer.");
    }

    std::string binary = "";
    while (n > 0) {
        binary = (n % 2 == 0 ? "0" : "1") + binary;
        n /= 2;
    }
    return binary.empty() ? "0" : binary;
}
